def lempel_golomb(p, g, h):
    """Lempel-Golomb construction: order p-2"""
    log_h = {}
    val = 1
    for i in range(p-1):
        log_h[val] = i
        val = (val * h) % p

    perm = []
    for i in range(1, p-1):  # i = 1 to p-2
        gi = pow(g, i, p)
        val = (1 - gi) % p
        if val == 0:
            return None
        perm.append(log_h[val])
    return perm

def is_primitive_root(g, p):
    n = p - 1
    val = 1
    for i in range(1, n+1):
        val = (val * g) % p
        if val == 1 and i < n:
            return False
    return True

