def bron_kerbosch(R, P, X, adj, best):
    if not P and not X:
        if len(R) > len(best[0]):
            best[0] = R.copy()
        return

    if len(R) + len(P) <= len(best[0]):
        return  # pruning

    # Choose pivot with max connections to P
    pivot = max(P | X, key=lambda v: sum(1 for u in P if adj[v][u]))

    for v in list(P - set(neighbors(pivot, adj, P))):
        neighbors_v = set(u for u in range(44) if adj[v][u])
        bron_kerbosch(R | {v}, P & neighbors_v, X & neighbors_v, adj, best)
        P.remove(v)
        X.add(v)

