from itertools import combinations

def compute_girth(adj, n):
    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        queue = deque([(start, -1)])
        while queue:
            node, parent = queue.popleft()
            for nb in adj[node]:
                if nb == parent:
                    continue
                if dist[nb] == -1:
                    dist[nb] = dist[node] + 1
                    queue.append((nb, node))
                else:
                    cycle_len = dist[node] + dist[nb] + 1
                    min_cycle = min(min_cycle, cycle_len)
