import random

def check_k_colorable(adj, n, k):
    """Check if graph is k-colorable using backtracking"""
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            if all(colors[u] != c for u in adj[v]):
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

